INSERT INTO product (id, name, category_id, description, image, price, stock, sales, status, create_time, update_time) VALUES
(101, 'NCM811 圆柱电芯 21700 5000mAh',        1, '车用级高镍三元圆柱电芯，能量密度≥300Wh/kg，内阻≤20mΩ，支持 3C 放电，循环寿命≥1500 次，适合动力/储能场景。',                        '/images/21700.png',           28.80,  60000, 1860, 1, '2026-08-01 09:00:00', '2026-08-28 18:12:10'),
(102, '磷酸铁锂 18650 电芯 3200mAh',           1, 'A 品 LFP 圆柱电芯，高安全性，针刺不起火，循环≥3000 次，适用家储与电动车低速车配套。',                                     '/images/18650.png',           12.90, 120000, 3240, 1, '2026-08-02 10:30:00', '2026-09-01 11:05:41'),
(103, '软包聚合物锂电池 3.7V 10Ah',            1, '超薄软包电芯，铝塑膜封装，内阻低，适合无人机、便携设备、医疗电源，循环≥800 次。',                                            '/images/1.png',                68.00,  18000,  720, 1, '2026-08-03 14:00:00', '2026-08-30 22:33:00'),
(104, '方形铝壳电芯 3.2V 280Ah LFP',           1, '大厂 A 品方形铝壳磷酸铁锂电芯，激光焊密封，容量公差±2%，大模组 ESS 标配，循环≥6000 次。',                                  '/images/2 .png',              480.00,   5600,  560, 1, '2026-08-04 09:20:00', '2026-08-29 16:44:21'),
(105, '锂电池模组 48V 20Ah（13S10P）',         1, '18650 组合 13S10P 锂电池模组，带熔丝+均衡板，可直接替换铅酸，适用电摩/观光车/AGV。',                                      '/images/3.png',              1280.00,   3200,  420, 1, '2026-08-05 11:40:00', '2026-08-28 21:06:15'),
(106, '32700 磷酸铁锂圆柱电芯 6000mAh',        1, '大容量 32700 LFP 圆柱，大电流 1C 持续放电，适用储能与备用电源，循环≥3500 次。',                                           '/images/4.png',                22.50,  80000, 1580, 1, '2026-08-06 15:20:00', '2026-09-01 09:55:02'),
(107, '低温高倍率圆柱 18650 2500mAh',          1, '-40℃ 放电保持率≥80%，支持 10C 脉冲放电，极寒地区特种车辆、军品电源专用。',                                                   '/images/5 .png',               38.00,  12000,  210, 1, '2026-08-07 08:50:00', '2026-08-30 10:15:30'),
(108, '高镍 NCM955 硅碳负极圆柱 4680',         1, '4680 无极耳圆柱电芯，硅碳负极，能量密度 350+Wh/kg，适配新一代电动乘用车。',                                                  '/images/6 .png',               85.60,   8800,  135, 1, '2026-08-08 17:10:00', '2026-08-27 14:22:08'),
(109, '无人机高倍率 软包 6S 22000mAh',         1, '植保/测绘无人机专用 6S 高压软包组，25C 持续放电，可 12 分钟快速补电。',                                                      '/images/bms.png',              3280.00,    800,   68, 1, '2026-08-09 09:30:00', '2026-08-26 20:01:55'),
(110, '启动型磷酸铁锂电池 12.8V 60Ah',         1, '汽车/工程机械 12V 启动替换，CCA≥1200A，-30℃ 正常启动，比铅酸轻 70%。',                                                      '/images/12V-module.png',       980.00,   1800,  310, 1, '2026-08-10 13:40:00', '2026-08-29 15:10:10'),
(111, '钠离子圆柱 18650 2000mAh 样品',         1, '新一代钠电圆柱样品电芯，低温性能优秀、成本低，适合低速车与储能（提供 100 只起订小批量）。',                                   '/images/18650.png',            9.90,   30000,   48, 1, '2026-08-11 16:00:00', '2026-08-25 18:30:00'),
(112, '高尔夫球车 48V 100Ah 锂电池组',         1, '旅游景区/厂区高尔夫球车 48V 100Ah 专用 LFP 电池组，BMS 保护+CAN 通信，支持原车直装。',                                      '/images/48Velectrocar.png',   5880.00,    600,  162, 1, '2026-08-12 10:20:00', '2026-08-28 10:48:41');
