(118, '乘用车 NCM 62kWh 标准续航 PACK',        2, 'A级纯电轿车 62 度电 NCM PACK，590 模组，CLTC 520km，兼容 400V 快充。',                                                    '/images/5 .png',            52800.00,    260,  210, 1, '2026-08-06 10:30:00', '2026-08-31 18:20:18'),
(119, '换电式重卡 LFP 432kWh 电池盒',          2, '干线重卡换电标准 432 度电电池盒，2+2 双仓换电，1.5 分钟完成换电流程。',                                                     '/images/6 .png',           328000.00,    20,     8, 1, '2026-08-07 15:10:00', '2026-08-24 09:05:00'),
(120, '低速老年代步车 60V 30Ah 电池包',        2, '合规低速代步车 60V30Ah 专用铁锂包，防撞外壳+绝缘护套，配车载充电器。',                                                     '/images/21700.png',          1980.00,   1500,  486, 1, '2026-08-08 09:40:00', '2026-08-30 09:25:32'),
(121, '混动 PHEV 刀片电池 20kWh',              2, 'DM-i 架构 PHEV 专用 20 度电刀片铁锂电池，CTB 一体化结构，满足整车碰撞五星安全。',                                          '/images/portable-power.jpg.png', 26800.00, 520,    95, 1, '2026-08-09 11:50:00', '2026-08-28 14:50:02'),
(122, '矿用宽体车 LFP 350kWh 动力电池',        2, '非公路矿用宽体自卸车 350 度电高压动力电池，抗震+防尘+液冷，日作业 20 小时无忧。',                                          '/images/48Velectrocar.png', 258000.00,    30,    12, 1, '2026-08-10 16:20:00', '2026-08-23 10:35:18');
