-- =============================================================
-- 绿链锂电采购平台 · 商品种子数据（追加式，不清空原有数据）
-- 生成时间：2026-09-02
-- 数据规模：+48 条 SKU（覆盖锂电池 / 动力电池 / 储能电池 / BMS / 充电配件 5 大分类）
-- 执行方式：mysql -uroot -p123456 --default-character-set=utf8mb4 green_chain < product_seed.sql
-- 说明：
--   1) 商品显式主键 id 101~148，避免与 1~30 初始化数据冲突
--   2) 图片全部引用 frontend/public/images 已存在的资源（MinIO 不启动也能正常预览）
--   3) 分类映射：1=锂电池  2=动力电池  3=储能电池  4=电池管理系统(BMS)  6=充电配件
--   4) 销量 sales 设计：每类保留 1~2 个爆款、3~5 个中销、其余长尾，让 Dashboard 饼图与 Redis 榜单更真实
-- =============================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
USE green_chain;

-- ========== 分类 1：锂电池（圆柱电芯 / 方形 / 软包 / 电池组）共 12 条，id 101~112 ==========

-- ========== 分类 2：动力电池（乘用车 / 商用车 / 专用车 PACK）共 10 条，id 113~122 ==========

-- ========== 分类 3：储能电池（户用 / 工商业 / 微网 / 便携）共 10 条，id 123~132 ==========

-- ========== 分类 4：电池管理系统（BMS / 保护板 / 采集板）共 8 条，id 133~140 ==========

-- ========== 分类 6：充电配件（充电器 / 枪 / 桩 / 线材 / 均衡仪）共 8 条，id 141~148 ==========

SET FOREIGN_KEY_CHECKS = 1;
